#include <algorithm>
#include <fstream>
#include <iostream>
#include <vector>
#include <deque>
using namespace std;using Row=vector<pair<int,int>>;
struct Node{Row row;int kind,source,var;};
int main(int argc,char**argv){ifstream in(argv[1]);ofstream trace(argv[2]);int p,n,N,F;in>>p>>n>>N>>F;vector<int>deg(N),bid(N,-1);vector<vector<int>>shift(n,vector<int>(N));for(int&i:deg)in>>i;for(auto&r:shift)for(int&i:r)in>>i;vector<Row>base(N);const int cutoff=*max_element(deg.begin(),deg.end());vector<deque<Node>>queue(cutoff+1);for(int j=0;j<F;j++){int len;in>>len;Row r(len);for(auto&[i,c]:r)in>>i>>c;if(!r.empty())queue[deg[r[0].first]].push_back({std::move(r),0,j,-1});}auto power=[&](int a,int b){long long out=1;while(b){if(b&1)out=out*a%p;a=(long long)a*a%p;b>>=1;}return(int)out;};int rank=0;for(int stage=0;stage<=cutoff;stage++)while(!queue[stage].empty()){Node src=std::move(queue[stage].front());queue[stage].pop_front();vector<int>r(N),red;for(auto[i,c]:src.row)r[i]=c;for(int i=0;i<N;i++)if(r[i]&&!base[i].empty()){int a=r[i];red.push_back(bid[i]);for(auto[k,c]:base[i]){r[k]=(r[k]-(long long)a*c)%p;if(r[k]<0)r[k]+=p;}}int pi=0;while(pi<N&&!r[pi])pi++;if(pi==N)continue;if(deg[pi]>stage){queue[deg[pi]].push_back(std::move(src));continue;}int iv=power(r[pi],p-2);Row b;for(int i=pi;i<N;i++)if(r[i])b.emplace_back(i,(long long)r[i]*iv%p);base[pi]=b;bid[pi]=rank;trace<<rank<<" "<<pi<<" "<<src.kind<<" "<<src.source<<" "<<src.var<<" "<<red.size();for(int id:red)trace<<" "<<id;trace<<"\n";for(int j=0;j<n;j++){Row v;for(auto[k,c]:b)if(shift[j][k]>=0)v.emplace_back(shift[j][k],c);if(!v.empty())queue[stage+1].push_front({std::move(v),1,rank,j});}rank++;}ofstream order(argv[3]);for(int i=0;i<N;i++)if(bid[i]>=0)order<<i<<" "<<bid[i]<<"\n";if(argc>4){ofstream out(argv[4]);out<<rank<<"\n";for(int i=0;i<N;i++)if(bid[i]>=0){int len=0;for(auto[k,c]:base[i])if(deg[k]==deg[i])len++;out<<len;for(auto[k,c]:base[i])if(deg[k]==deg[i])out<<" "<<k<<" "<<c;out<<"\n";}}cout<<rank<<"\n";}
